@deco.set_separate_app_context(MONACO_APP_NAME)
def toggle_destination_from_auto_dicom_export_dicom_destinations_dialog(destinationCheckboxLabel: str, enableCheckbox: bool = True, scrollDownList=False) -> None:
    """Locates the DICOM Destinations dialog (appears when using Auto Dicom Export) and finds the checkbox within the destination list.
    Then toggles it to an enabled/checked or disabled/unchecked state.

    :param destinationCheckboxLabel: string value of the destination label (e.g. "MIM_AE", "TQA_AE") whose checkbox will be toggled
    :param enableCheckbox: bool value to determine if the checkbox should be enabled/checked (True) or disabled/unchecked (False)
    :param scrollDownList: bool value to determine if the listview should be scrolled down to find the checkbox
    """
    if CommonActions.find_object(MonacoDicomExportObjects.dicom_Destinations_Dialog) is not None:

        if scrollDownList:
            press_auto_dicom_export_dicom_destinations_scroll_down_button()

        destination_list = CommonActions.get_child_objects(MonacoDicomExportObjects.dicom_Destinations_ListView)

        # Group the Destination ListView child objects into labels and buttons lists. The indexes for both groups of lists
        # should map to one another as there is always a label ListViewItem object that corresponds to a checkbox Button object.

        # Get the list of destination label objects
        destination_list_view_items = CommonActions.get_child_objects_by_object_type(
            destination_list,
            searchText="ListViewItem")

        # Get the list of checkbox button objects
        destination_list_checkboxes = CommonActions.get_child_objects_by_object_type(
            destination_list,
            searchText="Button")

        # Search for the specified label value text string and if found get the index
        associated_checkbox_index: int
        for idx, destination_label_value in enumerate(destination_list_view_items):
            destination_label_obj = CommonActions.get_child_object_by_object_text(
                CommonActions.get_child_objects(destination_label_value),
                searchText=destinationCheckboxLabel)

            if destination_label_obj is not None:
                associated_checkbox_index = idx

                # NOTE: If the scroll down button is used to scroll the listview down, then the listview will only display a
                # maximum of 4 checkboxes at any one time and Squish in turn will only detect 4 checkbox/button objects.
                # However, the number of label objects (destination_label_obj) associated with the checkboxes that Squish
                # finds will always be at least one more (i.e. 5 label objects), although only 4 are typically visible to a user.
                # To account for this discrepancy, the associated_checkbox_index is decremented by 1 if the scrollDownList flag
                # is set to True and the associated_checkbox_index is the last item in the list view.
                if scrollDownList and associated_checkbox_index == len(destination_list_view_items) - 1:
                    associated_checkbox_index = associated_checkbox_index - 1
                break

        # Select or un-select the checkbox
        try:
            found_destination_checkbox = destination_list_checkboxes[associated_checkbox_index]

            try:
                # Check if the checkbox is already checked using image verification as the 'enabled' property of the checkbox/button object type
                # always reports True even when the the checbox is unchecked, so this property is not reliable for this check.

                dest_checkbox_checked_image_path = os.path.abspath(os.path.join(CommonMonacoOps.get_monaco_image_folder_path(),
                                                                                "dicom_export_checkbox_checked.png"))

                image_search_options = {"timeout": 3000, "threshold": 95.0}
                destination_checkbox_checked = CommonActions.wait_for_image_object(dest_checkbox_checked_image_path, image_search_options, found_destination_checkbox)
            except Exception as e:
                destination_checkbox_checked = None

            if enableCheckbox:
                #NOTE: 'enabled' property is always True so replaced with image verification
                #if destination_checkbox.enabled is not True: #type: ignore
                if destination_checkbox_checked is None:
                    CommonActions.left_click_object(found_destination_checkbox)
            else:
                #if destination_checkbox.enabled is True: #type: ignore
                if destination_checkbox_checked is not None:
                    CommonActions.left_click_object(found_destination_checkbox)
        except UnboundLocalError:
            print(f"{destinationCheckboxLabel} checkbox wasn't found inside the DICOM Destinations dialog. Check Monaco settings configuration")

@deco.set_separate_app_context(MONACO_APP_NAME)
def press_auto_dicom_export_dicom_destinations_scroll_down_button(pressDuration: float = 1) -> None:
    """Locates the DICOM Destinations dialog (appears when using Auto Dicom Export) > presses and holds
    the DOWN button on the scrollbar with the left mouse button for the duration specified.

    :param float pressDuration: value to set the duration of the DOWN button press. Button is released after this duration.
    """
    if CommonActions.find_object(MonacoDicomExportObjects.dicom_Destinations_Dialog) is not None:
        # The Scrollbar DOWN button is located using relative x, y coordinates from the DICOM Destintations CANCEL button
        cancel_btn = CommonActions.find_object(MonacoDicomExportObjects.dicom_Destinations_Cancel_Button)
        if cancel_btn is not None:
            CommonActions.mouse_press_hold_and_release_with_x_and_y_offset(cancel_btn, 70, -30, pressDuration)

