@deco.set_separate_app_context(MONACO_APP_NAME)
def click_auto_dicom_export_dicom_destinations_ok_button(dicomDialogDisappearTimeout: int = 30) -> None:
    """Locates the DICOM Destinations dialog (appears when using Auto Dicom Export) > clicks the OK button >
    then waits for the Dialog to disappear.

    :param dicomDialogDisappearTimeout: int value to set the timeout duration for the DICOM Destinations dialog to disappear
    """
    if CommonActions.find_object(MonacoDicomExportObjects.dicom_Destinations_Dialog) is not None:
        CommonActions.left_click_object(MonacoDicomExportObjects.dicom_Destinations_OK_Button)
        CommonActions.wait_for_object_to_disappear(MonacoDicomExportObjects.dicom_Destinations_Dialog, dicomDialogDisappearTimeout)

        try:
            # Acknowledge "Automatic DICOM Export has failed" dialog message if displayed
            if CommonActions.find_object(MonacoCoreObjects.monaco_Dialog, 5000) is not None:
                CommonActions.left_click_object(MonacoCoreObjects.monaco_Dialog_OK_Button)
        except FailedToFindObject:
            print("No Automatic DICOM Export failure message found. Nothing to acknowledge")


@deco.set_separate_app_context(MONACO_APP_NAME)
def toggle_checkbox_from_manual_dicom_export_destination_tree(destinationCheckboxLabel: str, enableCheckbox: bool = True) -> None:
    """Locates the MANUAL DICOM export dialog and finds the specified checkbox by name within the export destination list.
    Toggles it to an enabled state.

    :param destinationCheckboxLabel: string value of the destination label (e.g. "DCMWin", "MIM", "TQA_Plan" etc...) whose checkbox will be toggled
    :param enableCheckbox: bool value to determine if the checkbox should be enabled/checked (True) or disabled/unchecked (False)
    """
    if CommonActions.find_object(MonacoDicomExportObjects.dICOM_Export_Dialog) is not None:

        destination_list = CommonActions.get_child_objects(MonacoDicomExportObjects.dICOM_Export_Destination_ListView)

        destination_list_view_items = CommonActions.get_child_objects_by_object_type(
            destination_list,
            searchText="ListViewItem")

        destination_list_checkboxes = CommonActions.get_child_objects_by_object_type(
            destination_list,
            searchText="Button")

        associated_checkbox_index: int
        for idx, destination_value in enumerate(destination_list_view_items):
            destination_text = CommonActions.get_child_object_by_object_text(
                CommonActions.get_child_objects(destination_value),
                searchText=destinationCheckboxLabel)

            if destination_text is not None:
                associated_checkbox_index = idx
                break

        # Select or un-select the checkbox
        try:
            found_destination_checkbox = destination_list_checkboxes[associated_checkbox_index]

            try:
                # Check if the checkbox is already checked using image verification as the 'enabled' property of the checkbox/button object type
                # always reports True even when the the checbox is unchecked, so this property is not reliable for this check.

                dest_checkbox_checked_image_path = os.path.abspath(os.path.join(CommonMonacoOps.get_monaco_image_folder_path(),
                                                                                "dicom_export_checkbox_checked.png"))

                image_search_options = {"timeout": 3000, "threshold": 95.0}
                destination_checkbox_checked = CommonActions.wait_for_image_object(dest_checkbox_checked_image_path, image_search_options, found_destination_checkbox)
            except Exception as e:
                destination_checkbox_checked = None

            if enableCheckbox:
                if destination_checkbox_checked is None:
                    CommonActions.left_click_object(found_destination_checkbox)
            else:
                if destination_checkbox_checked is not None:
                    CommonActions.left_click_object(found_destination_checkbox)
        except UnboundLocalError:
            print(f"{destinationCheckboxLabel} checkbox wasn't found inside the DICOM Destinations dialog. Check Monaco settings configuration")


@deco.set_separate_app_context(MONACO_APP_NAME)
def toggle_single_checkbox_from_manual_dicom_export_destination_tree(destinationCheckboxLabel: str, enableCheckbox: bool = True) -> None:
    """ Locates the MANUAL DICOM export dialog and finds the specified checkbox by name within the export destination list.
    Toggles it to an enabled if enableCheckbo is True or disabled state if False.

    Note: This is an alternative method for toggling the destination checkboxes using the State() class and user32 api.

    :param destinationCheckboxLabel: string value of the destination label (e.g. "DCMWin", "MIM", "TQA_Plan" etc...) whose checkbox will be toggled
    :param enableCheckbox: bool value to determine if the checkbox should be enabled/checked (True) or disabled/unchecked (False)
    """
    if CommonActions.find_object(MonacoDicomExportObjects.dICOM_Export_Dialog) is not None:

        destination_list = CommonActions.get_child_objects(MonacoDicomExportObjects.dICOM_Export_Destination_ListView)

        destination_list_view_items = CommonActions.get_child_objects_by_object_type(
            destination_list,
            searchText="ListViewItem")

        destination_list_checkboxes = CommonActions.get_child_objects_by_object_type(
            destination_list,
            searchText="Button")

        associated_checkbox_index: int
        for idx, destination_value in enumerate(destination_list_view_items):
            destination_text = CommonActions.get_child_object_by_object_text(
                CommonActions.get_child_objects(destination_value),
                searchText=destinationCheckboxLabel)

            if destination_text is not None:
                associated_checkbox_index = idx
                break

        # Select or un-select the checkbox
        try:
            found_destination_checkbox = destination_list_checkboxes[associated_checkbox_index]
            #Note that the checkbox buttons have same id, the y value can be used to differentiate them.
            checkbox_button = State({"id": int(found_destination_checkbox.id), "y": found_destination_checkbox.y}) # type: ignore
            checkbox_button.value =  enableCheckbox
        except UnboundLocalError:
            print(f"{destinationCheckboxLabel} checkbox wasn't found inside the DICOM Destinations dialog. Check Monaco settings configuration")


@deco.set_separate_app_context(MONACO_APP_NAME)
def toggle_checkboxes_from_manual_dicom_export_destination_tree(destinationCheckboxLabels: list, enableCheckbox: bool = True) -> None:
    """Locates the MANUAL DICOM export dialog and finds the specified checkboxes by names within the export destination list.
    Toggles them to an enabled state if enableCheckbox is True, or to disabled state if False. Other checkboxes that are not in the list
    will be toggled to the opposite state.

    Note: This method for toggling the destination checkboxes is also using the State() class and user32 api.

    :param destinationCheckboxLabels: list of string values of the destination labels (e.g. "DCMWin", "MIM", "TQA_Plan" etc...) whose checkbox will be toggled
    :param enableCheckbox: bool value to determine if the checkbox should be enabled/checked (True) or disabled/unchecked (False)
    """
    if CommonActions.find_object(MonacoDicomExportObjects.dICOM_Export_Dialog) is not None:

        destination_list = CommonActions.get_child_objects(MonacoDicomExportObjects.dICOM_Export_Destination_ListView)

        destination_list_view_items = CommonActions.get_child_objects_by_object_type(
            destination_list,
            searchText="ListViewItem")

        destination_list_checkboxes = CommonActions.get_child_objects_by_object_type(
            destination_list,
            searchText="Button")
        print(f"destination_list_view_items: {len(destination_list_view_items)}")
        print(f"destination_list_checkboxes: {len(destination_list_checkboxes)}")

        # Build selected indices from visible destination labels (case-insensitive match).
        normalized_labels = {str(lbl).strip().lower() for lbl in destinationCheckboxLabels}
        selected_indices = set()

        for idx, destination_value in enumerate(destination_list_view_items):
            children = CommonActions.get_child_objects(destination_value)
            for child in children:
                if hasattr(child, "text"):
                    child_text = str(child.text).strip().lower() #type: ignore
                    if child_text in normalized_labels:
                        selected_indices.add(idx)
                        break

        if len(selected_indices) == 0:
            print(f"Warning: None of the destinations {destinationCheckboxLabels} were matched in the manual DICOM destination list.")

        # Destination rows and checkbox controls can mismatch in count/order, so only
        # operate over the index range that exists in both collections.
        max_items = min(len(destination_list_view_items), len(destination_list_checkboxes))
        for idx in range(max_items):
            found_destination_checkbox = destination_list_checkboxes[idx]
            value = enableCheckbox if idx in selected_indices else not enableCheckbox
            try:
                # Checkbox buttons share the same id. Pair with y-position to identify each row.
                checkbox_button = State({"id": int(found_destination_checkbox.id), "y": found_destination_checkbox.y}) # type: ignore
                # Avoid redundant writes when state already matches.
                if checkbox_button.value != value:
                    checkbox_button.value = value
                print(f"{idx}: {value}")
            except Exception as e:
                print(f"Skipping destination checkbox index {idx}. Failed to set value={value}. Reason: {e}")

