@deco.set_separate_app_context(MONACO_APP_NAME)
def map_machine(mapping:dict, remap:bool):
    """
    Map machine method.
    Note: If the machine is not found in the mapping dict or the mapping is empty, use itself.
          If the machine is already mapped, will try to remap if remap is True, otherwise, skip.

    :params: mapping (dict), the mapping of machine name pairs. If it is like {"":"NewName"}, all
               the  machines are mapped to "NewName".
             remap (bool), if need to remap if alreay mapped.
    """
    map_machine_list = CommonActions.get_child_objects(MapMachineObjects.map_Machine_ListView)
    map_machine_list_edits = CommonActions.get_child_objects_by_object_type(
        map_machine_list,
        searchText="Edit")

    grouped_by_y = {}
    for edit in map_machine_list_edits:
        y_value = edit.y # type: ignore
        if y_value not in grouped_by_y:
            grouped_by_y[y_value] = []
        grouped_by_y[y_value].append(edit)

    count = 0
    new_map = 0
    solo_name = next(enumerate(mapping.values()))[1].strip() if mapping and next(enumerate(mapping.keys()))[1] == "" else None #if mapping is  like{"":"NewName"}
    for item in grouped_by_y:
        count += 1
        if grouped_by_y[item][0].readonly == True:
            mapped_machine = State({"id": grouped_by_y[item][1].id, "x": grouped_by_y[item][1].x})
            if remap or not mapped_machine.value:
                mapped_machine.value = mapping.get(grouped_by_y[item][0].text,  grouped_by_y[item][0].text if not solo_name else solo_name)
                new_map += 1
        else:
            mapped_machine = State({"id": grouped_by_y[item][0].id, "x": grouped_by_y[item][0].x})
            if remap or not mapped_machine.value:
                mapped_machine.value = mapping.get(grouped_by_y[item][1].text, grouped_by_y[item][1].text if solo_name is None else solo_name)
                new_map += 1
    if count == 0:
        print("Error occurs as no machine available.")
    elif new_map == 0:
        print("No more mapping needed as already mapped.")
    else:
        print(f"{new_map} new mapping machine(s) added.")

