@deco.set_separate_app_context(MONACO_APP_NAME)
def click_export_button(dialogWaitTimeout: int = 900, acknowledge:bool=False) -> bool:
    """Locates the DICOM Export dialog > clicks the Export button > then waits for the Dialog to disappear.
       If export failed, will handle it by click on the OK button to acknowledge.

    :param: dialogWaitTimeout: int value to set the timeout duration for the export dialog to disappear
    :return: bool value to indicate if the export completed successfully or not.
    """
    if CommonActions.find_object(MonacoDicomExportObjects.dICOM_Export_Dialog) is not None:
        CommonActions.left_click_object(MonacoDicomExportObjects.dICOM_Export_Export_Button)
        ret = CommonActions.wait_for_object_one_to_disappear_or_object_two_to_appear(MonacoDicomExportObjects.dICOM_Export_Dialog,
                MonacoCoreObjects.monaco_Dialog, dialogWaitTimeout)
        if ret == "notification" and acknowledge:
            CommonActions.left_click_object(MonacoCoreObjects.monaco_Dialog_OK_Button)
        else:
            return ret == "success"
    return False

