@deco.set_separate_app_context(MONACO_APP_NAME)
def override_values(patID = None, patName=None, blockAperturesID = None, planID = None):
    """
    OVerrides the values with the provided values.

    :params: patID, Patient ID, patName, Patient Name, blockAperturesID, block/apertures ID, PlanID, Plan ID.
            each of them defaults to None.
    """
    try:
        if patID or patName:
            click_use_monaco_patient_button(False)
        if patID:
            pat_id_edit = State(MonacoDicomExportObjects.dICOM_Export_Patient_ID_Edit)
            pat_id_edit.value = patID
        if patName:
            pat_name_edit = State(MonacoDicomExportObjects.dICOM_Export_Patient_Name_Edit)
            pat_name_edit.value = patName
        if blockAperturesID:
            block_apertures_id_edit = State(MonacoDicomExportObjects.dICOM_Export_Block_Apertures_ID_Edit)
            block_apertures_id_edit.value = blockAperturesID
        if planID:
            plan_id_edit = State(MonacoDicomExportObjects.dICOM_Export_Plan_ID_Edit)
            plan_id_edit.value = planID
    except Exception as e:
        print(str(e))

