@deco.set_separate_app_context(MONACO_APP_NAME)
def affirm_mosaiq_options():
    """
    Affirm current Mosaiq options on the Mosaiq Options dialog
    """
    CommonActions.left_click_object(MosaiqOptions.mosaiq_Options_OK_Button)

@deco.set_separate_app_context(MONACO_APP_NAME)
def select_mosaiq_tolerance_table(toleranceName:str):
    """
    Select tolerance option from the list of Mosaiq tolerance table.

    :param: toleranceName (str), the option to be selected.
    """
    CommonActions.click_item(MosaiqOptions.mosaiq_Options_ListView, toleranceName, click_screen_area=True)


@deco.set_separate_app_context(MONACO_APP_NAME)
def set_plan_intent(intent:str):
    """
    Set plan intent.

    :param: intent (str), the intent to be set.
    """
    plan_intent = State(MosaiqOptions.mosaiq_Options_Plan_Intent_ComboBox)
    plan_intent.value = intent #"Verification"

@deco.set_separate_app_context(MONACO_APP_NAME)
def set_dose_rate(doseRate:str):
    """
    Set dos rate.

    :param: doseRate (str), the dose rate to be set.
    """
    CommonActions.mouse_move_and_press(MosaiqOptions.mosaiq_Options_Dose_Rate_ListViewItem)
    CommonActions.press_key_sequence_ctrl_a()
    time.sleep(0.3)
    CommonActions.press_delete_key()
    time.sleep(0.2)
    CommonActions.native_text_type(doseRate)

@deco.set_separate_app_context(MONACO_APP_NAME)
def acknowledge_question(confirmed:bool):
    """
    Acknowledge if question window pops up.

    :param: confirmed (bool), True if confirmed OK, False if to cancel.
    """
    if CommonActions.find_any_object([{"text": "Monaco", "type": "Window"}, {"text": "Monaco", "type": "Dialog"}], 500):
        if confirmed:
            CommonActions.left_click_object({"text": "OK", "type": "Button"})
        else:
            CommonActions.left_click_object({"text": "Cancel", "type": "Button"})